import heapq

def match(orders):
    trades = []
    buy_book = []   # heap of (-price, seq, id)
    sell_book = []  # heap of (price, seq, id)
    orders_info = {}  # id -> {'side','price','qty','active','seq'}
    seq_counter = 0

    def pop_valid(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            info = orders_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
            else:
                return item
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info and info['active']:
                info['active'] = False
            continue

        if typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            _, oid, side, price, qty = order

        remaining = qty
        info = {'side': side, 'price': price, 'qty': remaining, 'active': True, 'seq': seq_counter}
        orders_info[oid] = info
        seq_counter += 1

        opp_heap = sell_book if side == 'buy' else buy_book

        while remaining > 0:
            top = pop_valid(opp_heap)
            if top is None:
                break
            opp_id = top[2]
            opp_info = orders_info[opp_id]
            opp_price = opp_info['price']

            if typ != 'market':
                if side == 'buy' and price < opp_price:
                    break
                if side == 'sell' and price > opp_price:
                    break

            trade_qty = min(remaining, opp_info['qty'])
            if side == 'buy':
                trades.append([oid, opp_id, opp_price, trade_qty])
            else:
                trades.append([opp_id, oid, opp_price, trade_qty])

            remaining -= trade_qty
            opp_info['qty'] -= trade_qty
            info['qty'] = remaining

            if opp_info['qty'] == 0:
                opp_info['active'] = False

        info['qty'] = remaining

        if remaining == 0:
            info['active'] = False
        elif typ == 'limit':
            info['active'] = True
            if side == 'buy':
                heapq.heappush(buy_book, (-price, info['seq'], oid))
            else:
                heapq.heappush(sell_book, (price, info['seq'], oid))
        else:
            # ioc or market with leftover qty: discard remainder
            info['active'] = False

    return trades

